import fs from 'node:fs/promises';
import {RemoteD1Database} from '../runner/report2-d1-adapter.mjs';
import {loadDailyUsageAggregate,evaluateDailyReservationBudget,reserveRunBudget,finalizeRunUsage} from '../runner/d1-preaction-budget-guard.mjs';
const now=Date.now(),db=new RemoteD1Database(process.env.REPORT2_D1_BRIDGE_URL,process.env.REPORT2_D1_BRIDGE_TOKEN),day=new Date(now).toISOString().slice(0,10),reservation={rows_read:1000,rows_written:16},id='CONTINUOUS_CADENCE_READ:'+process.env.GITHUB_RUN_ID;
const out={schema:'CONTINUOUS_CLOUD_CADENCE_EXACT_READ_V1',read_head:process.env.GITHUB_SHA,cloud_run:process.env.GITHUB_RUN_ID,read_ts:now,sourceHTTP:0,MAIN:0,Telegram:0,task_writes:0,source_clocks_refreshed:false,actual_ENTRY:false,full_project_complete:false};
out.admission=evaluateDailyReservationBudget({daily:await loadDailyUsageAggregate(db,now),nextReservation:reservation,maxDailyReads:3500000,maxDailyWrites:70000});
if(out.admission.allowed){await reserveRunBudget(db,{reservationId:id,now,reservation});try{
out.poll=await db.prepare('SELECT day_key,last_bucket,polls FROM report2_trigger_kick_poll WHERE day_key=?1 LIMIT 1').bind(day).first();
out.kicks=(await db.prepare('SELECT day_key,slot,task_id,kick_ts FROM report2_trigger_kick_slot WHERE day_key=?1 ORDER BY slot LIMIT 3').bind(day).all()).results;
out.collector_slots=(await db.prepare('SELECT bucket,state,started_ts,completed_ts,external_requests,rows_read,rows_written,status FROM report2_public_collector_usage_v1 WHERE actor=?1 AND generation=?2 AND bucket>=?3 AND bucket<=?4 ORDER BY bucket LIMIT 6').bind('HUB_PUBLIC_COLLECTOR','MY_REPORT_2_CURRENT_20260928_CANONICAL_RUNTIME_V12_CONTRACT_INTEGRITY_20M',1791492300000,Math.floor(now/300000)*300000).all()).results;
const c={contract:'FIL-USDT',direction:'LONG',publication:'PUB:7577f0f3cb87c4251f3dfe6d08e8cdec3f397999',run_id:'1791487535792-1791487551019',snapshot:'S392:FIL-USDT:1791487668251',fingerprint:'54be12ff375dd29c7c02272da610fa48f2aa9dffa101b53ed7b82f5137279879'};
out.original_FIL={...c,receipt:await db.prepare("SELECT b.publication_id,b.run_id,b.snapshot_id,b.analytical_fingerprint,b.observed_ts,b.wave_id,b.lifecycle_event,d.state,d.telegram_message_id,d.sent_ts,d.last_error FROM v3_dispatch_publication_binding_shadow b JOIN v3_telegram_dispatch_shadow d ON d.idempotency_key=b.idempotency_key AND d.contract=b.contract_code AND d.direction=b.direction AND d.wave_id=b.wave_id WHERE b.publication_id=?1 AND b.contract_code=?2 AND b.direction=?3 AND b.run_id=?4 AND b.snapshot_id=?5 AND b.analytical_fingerprint=?6 LIMIT 1").bind(c.publication,c.contract,c.direction,c.run_id,c.snapshot,c.fingerprint).first(),task:await db.prepare('SELECT task_id,publication_id,contract_code,run_id,snapshot_id,due_ts,expires_ts,state,attempt_count,last_result,created_ts,updated_ts FROM v3_recheck_task_shadow WHERE publication_id=?1 AND contract_code=?2 AND direction=?3 AND run_id=?4 AND snapshot_id=?5 LIMIT 1').bind(c.publication,c.contract,c.direction,c.run_id,c.snapshot).first()};
const u=db.usageSnapshot();if(u.unknown_ops||u.rows_read>950||u.rows_written>12||u.requests>20)throw Error('READ_ENVELOPE_EXCEEDED');
out.status='EXACT_CADENCE_AND_ORIGINAL_FIL_READ_CLOSED';
}catch(e){out.status='READ_FAILED';out.error_code=e.message==='READ_ENVELOPE_EXCEEDED'?e.message:'D1_READ_FAILURE';}finally{out.finalized_usage=await finalizeRunUsage(db,{reservationId:id,sourceRunId:process.env.GITHUB_RUN_ID,usage:db.usageSnapshot()});}}else out.status='D1_ADMISSION_BLOCKED';
out.d1_usage=db.usageSnapshot();await fs.mkdir('audit-output',{recursive:true});await fs.writeFile('audit-output/current-cadence-read.json',JSON.stringify(out,null,2)+'\n');console.log(JSON.stringify({status:out.status,poll:out.poll,slots:out.collector_slots,original_FIL_SENT:out.original_FIL?.receipt?.state,sourceHTTP:0,Telegram:0,d1_usage:out.d1_usage}));if(out.status!=='EXACT_CADENCE_AND_ORIGINAL_FIL_READ_CLOSED')process.exitCode=1;
